def _cut(s, n):
    return s if len(s) <= n else s[:n].rsplit(" ", 1)[0] + "…"


def _tail(s, n):
    s = re.sub(r"\s+", " ", s).strip()
    if len(s) <= n:
        return s
    s = s[-n:]
    return "…" + (s.split(" ", 1)[1] if " " in s[:24] else s)


def _clean():  # the 328: the problems of hard.json whose overlap flag is 'none'
    hard = json.load(open(DATA["problems"]))
    flags = json.load(open(DATA["flags"]))["sets"]["hard"]["flags"]
    clean = sorted(int(i) for i, f in flags.items() if f["flag"] == "none")
    assert len(clean) == DATA["n"], len(clean)
    return hard, clean


def _rows():  # per cell, the stored rows by problem; None when a job's rows are not in runs/
    out = {}
    for k, _cell, _kind, _s, job in CELLS:
        path = f"runs/{job}/answers.jsonl"
        if not os.path.exists(path):
            return None
        rows = {}
        for line in open(path):
            r = json.loads(line)
            assert r["problem_index"] not in rows, (path, r["problem_index"])
            rows[r["problem_index"]] = r
        out[k] = rows
    return out


def _build(rows):  # PROBLEMS from the rows, graded again with grader v3; run from the repository root
    from studies.rlneurons.lib import rln4_lib
    hard, clean = _clean()
    out, v3 = [], {k: [] for k in KEYS}
    for i in clean:
        rs = [rows[k][i] for k in KEYS]
        assert all(r["gold"] == hard[i]["answer"] for r in rs), i
        g = [rln4_lib.grade_v3(hard[i]["answer"], r["text"]) for r in rs]
        for k, r, x in zip(KEYS, rs, g):
            assert r.get("score_v3", x["score_v3"]) == x["score_v3"], (k, i, "stored v3 score differs from the rescore")
            v3[k].append(x["score_v3"])
        out.append([i, hard[i]["source"], _cut(hard[i]["problem"], 420), hard[i]["answer"],
                    "".join(("k" if x["score_v3"] else "c") if r["cap_hit"] else ("r" if x["score_v3"] else "w") for r, x in zip(rs, g)),
                    [r["n_new"] for r in rs], [_cut(x["extracted_v3"] or "", 36) for x in g],
                    [_tail(r["text"], 80) for r in rs[:N_ENDINGS]]])
    return out, v3


def _code_rows():  # per code cell, the stored rows in file order; None when a job's rows are not in runs/
    out = {}
    for k, _cell, _kind, _s, job in CODE_CELLS:
        path = f"runs/{job}/answers.jsonl"
        if not os.path.exists(path):
            return None
        out[k] = [json.loads(line) for line in open(path)]
    return out


def _fresh_rows():  # the edit's rows per sample, and the first sample's rows of Base + cue, by problem; None when not in runs/
    out, paths = {}, [(k, f"runs/{j}/answers.jsonl") for k, j in zip(("e0", "e1", "e2", "e3"), FRESH_JOBS["edit"])] + \
        [("b0", f"runs/fresh/{FRESH_JOBS['base'][0]}/answers.jsonl")]
    for k, path in paths:
        if not os.path.exists(path):
            return None
        rows = [json.loads(line) for line in open(path)]
        out[k] = {r["problem_index"]: r for r in rows}
        assert len(out[k]) == len(rows) == DATA["fresh"]["n"], path
    return out


def _fresh_refs():  # the committed Base + cue and RL rows, by (sample, problem index)
    out = {}
    for arm, path in DATA["fresh"]["rows"].items():
        rows = [json.loads(line) for line in open(path)]
        out[arm] = {(r["sample"], r["problem_index"]): r for r in rows}
        assert len(out[arm]) == len(rows) == 4 * DATA["fresh"]["n"] and all(r["attempt"] == 0 for r in rows), path
        assert all(r["seed"] == DATA["fresh"]["seed"] + 10000 * s + i for (s, i), r in out[arm].items()), path
    return out


_outcome = lambda r: ("k" if r["score_v3"] else "c") if r["cap_hit"] else ("r" if r["score_v3"] else "w")


def _fresh_build(rows):  # FRESH_PROBLEMS from the rows; the edit's answers graded again with grader v3
    from studies.rlneurons.lib import rln4_lib
    F, ref = DATA["fresh"], _fresh_refs()
    out = []
    for p in json.load(open(F["problems"])):
        i = p["index"]
        edit = [rows[f"e{s}"][i] for s in range(4)]
        for s, r in enumerate(edit):
            x = rln4_lib.grade_v3(p["answer"], r["text"])
            assert (x["score_v3"], x["extracted_v3"]) == (r["score_v3"], r["extracted_v3"]), (i, s, "stored v3 differs from the rescore")
            assert r["seed"] == F["seed"] + 10000 * s + i and r["attempt"] == 0, (i, s)
        b0 = rows["b0"][i]
        assert all(b0[k] == ref["base"][(0, i)][k] for k in ("n_new", "cap_hit", "score_v3", "extracted_v3", "seed")), i
        rs = [ref["base"][(s, i)] for s in range(4)] + edit + [ref["rl"][(s, i)] for s in range(4)]
        assert all(r["gold"] == p["answer"] for r in rs), i
        out.append([i, p["source"], p["source_id"], p["date"], _cut(p["problem"], 420), p["answer"], "".join(map(_outcome, rs)),
                    [r["n_new"] for r in rs], [_cut(r["extracted_v3"] or "", 36) for r in rs],
                    [_tail(b0["text"], 80), _tail(edit[0]["text"], 80)]])
    return out


def _task(prompt):  # the problem as the model saw it, without the instruction around it
    head, rest = prompt.split("\n\n", 1)
    assert head.startswith("Solve the following code problem step by step."), head
    end = "Remember to put your solution inside the ```\npython\nCODE\n``` tags"
    assert rest.endswith(end), rest[-80:]
    return rest[:-len(end)].strip()


def _code_build(rows):  # CODE_PROBLEMS from the rows
    uids = [r["uid"] for r in rows["c0"]]
    assert len(uids) == DATA["code"]["n"] == len(set(uids))
    out = []
    for j, u in enumerate(uids):
        rs = [rows[k][j] for k in CODE_KEYS]
        assert all(r["uid"] == u and r["prompt"] == rs[0]["prompt"] for r in rs), u
        o = "".join(("k" if r["passed"] else "c") if r["cap_hit"] else "r" if r["passed"] else "n" if r["mode"] == "none" else "w"
                    for r in rs)
        err = []
        for r in rs:
            lines = [x for x in r["stderr_tail"].strip().split("\n") if x.strip()]
            err.append("" if r["passed"] or r["mode"] == "none" else "timeout" if r["exit"] == "timeout"
                       else _cut(lines[-1].strip(), 44) if lines else "")
        out.append([u, _cut(_task(rs[0]["prompt"]), 320), o, [r["n_new"] for r in rs], err,
                    [_tail(r["text"], 80) for r in rs[:N_CODE_ENDINGS]]])
    return out


# Counts from PROBLEMS, per key of CELLS: right (r or k), cut off (c or k), and right on the problems Base + cue finishes
_col = {k: j for j, k in enumerate(KEYS)}
_count = lambda k, chars: sum(p[4][_col[k]] in chars for p in PROBLEMS)
_fin0 = [p for p in PROBLEMS if p[4][_col["0"]] in "rw"]
COUNTS = {k: {"right": _count(k, "rk"), "cut": _count(k, "ck"), "right_finished": _count(k, "r"), "finished": _count(k, "rw"),
              "on_base_finished": sum(p[4][_col[k]] in "rk" for p in _fin0)} for k in KEYS}
DATA["base_finished"] = len(_fin0)

_C, _d = DATA["cells"], DATA["diff"]
_m = lambda x: str(x).replace("-", "−")  # the minus sign of the site
_pts = lambda x: f"{x:+.1f}".replace("-", "−")
_iv = lambda c: f"{_m(round(c[0], 1))} to {_m(round(c[1], 1))}"
_pct = lambda k: f"{100 * _C[k]['add_rel']:.2f} %"
_seq = lambda field, keys: ", ".join(str(_C[k][field]) for k in keys)
_TOP = ["m1", "0", "0.5", "1", "1.5", "2", "3"]
_RAND = ["rm1", "r1", "r1.5", "r2", "r3"]
_S, _R = DATA["sft"], DATA["rep"]
_rf = lambda k: COUNTS[k]["right_finished"] / COUNTS[k]["finished"]
_lo_rf, _hi_rf = min(_rf(k) for k in ("0", "0.5", "1", "1.5")), max(_rf(k) for k in ("0", "0.5", "1", "1.5"))
_rr = [_C[k]["right"] for k in _RAND]
_rc = [_C[k]["cut"] for k in _RAND]

# Counts from CODE_PROBLEMS, per key of CODE_CELLS: passed (r or k), cut off (c or k), no code block (n, or cut off and
# not passed with no block: the readout's no_block counts every answer with no code block)
_ccol = {k: j for j, k in enumerate(CODE_KEYS)}
CODE_COUNTS = {k: {"passed": sum(p[2][j] in "rk" for p in CODE_PROBLEMS), "cut": sum(p[2][j] in "ck" for p in CODE_PROBLEMS),
                   "unfinished": sum(p[2][j] in "ckn" for p in CODE_PROBLEMS)} for k, j in _ccol.items()}
_K, _kd = DATA["code"]["cells"], DATA["code"]["diff"]

# Counts from FRESH_PROBLEMS, per key ("0" Base + cue, "1.5" the edit, "rl") and sample: right (r or k), cut off (c or k)
_FG = {"0": 0, "1.5": 4, "rl": 8}
FRESH_COUNTS = {k: {"right": [sum(p[6][j + s] in "rk" for p in FRESH_PROBLEMS) for s in range(4)],
                    "cut": [sum(p[6][j + s] in "ck" for p in FRESH_PROBLEMS) for s in range(4)]} for k, j in _FG.items()}
_F = DATA["fresh"]
_fm = lambda k: f"{sum(_F['right'][k]) / 4:g}"  # the mean of the 4 samples: 48.25, 50.5, 29.5
_fr = lambda field, k: f"{min(_F[field][k])} to {max(_F[field][k])}"
_MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"]
_day = lambda d: f"{int(d[8:])} {_MONTHS[int(d[5:7]) - 1]} {d[:4]}"
_fiv = lambda x: f"{_pts(x[0])} points, 95 % interval {_m(x[1])} to {_m(x[2])}"

# The split (DATA["split"]): its numbers in the site's forms
_P = DATA["split"]
_PG = _P["groups"]
_civ = lambda x: f"{_pts(x[0])} points, 90 % interval {_m(x[1])} to {_m(x[2])}"
_FIN = 100 - _PG["CH"]["share"][0]  # the share of the gain on problems Base + cue finished: FR + FW, 1 minus CH per resample
_M2, _M1 = DATA["m500_2"], DATA["m500_m1"]

